export function bindToolbar(ctx,simulation,focus){
 const{state}=ctx,$=s=>document.querySelector(s),listeners=[];let timer;
 const listen=(el,type,fn)=>{el.addEventListener(type,fn);listeners.push(()=>el.removeEventListener(type,fn));};
 const names={day:'Day',sunset:'Sunset',night:'Night'},next={day:'sunset',sunset:'night',night:'day'},paths={day:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.4 1.4m11.2 11.2L19 19M19 5l-1.4 1.4M6.4 17.6 5 19"/>',sunset:'<path d="M2 17h20M5 14a7 7 0 0 1 14 0M12 2v3M3 7l2 1m16-1-2 1M5 21h14"/>',night:'<path d="M19.5 15.5A8 8 0 0 1 8.5 4.5 8 8 0 1 0 19.5 15.5Z"/>'};
 function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),2400);}
 function refresh(){document.body.dataset.time=state.timeMode;document.body.classList.toggle('night',state.timeMode==='night');$('#time-name').textContent=names[state.timeMode];$('#time-icon').innerHTML=paths[state.timeMode];$('#time').setAttribute('aria-label',`Time: ${names[state.timeMode]}. Switch to ${names[next[state.timeMode]]}.`);$('#orbit').setAttribute('aria-pressed',String(state.orbit));$('#pause').setAttribute('aria-pressed',String(state.paused));$('#pause span').textContent=state.paused?'Play':'Pause';$('#status').textContent=state.paused?'A little pause in the Pink City.':simulation.pendingRestoration.people?'People will return when the crossing clears.':simulation.pendingRestoration.traffic?'Traffic will return when the crossing clears.':{day:'Open shutters. Everyday stories.',sunset:'Golden sandstone. A cup of chai.',night:'The bazaar glows softly after dark.'}[state.timeMode];for(const kind of['traffic','people']){const b=$('#'+kind),mode=state[kind+'Mode'];b.dataset.mode=mode;b.setAttribute('aria-pressed',String(mode==='active'));b.setAttribute('aria-label',`${kind}: ${mode}. Click to ${{active:'pause',paused:'hide',hidden:'resume'}[mode]}.`);}}
 function setTime(mode){if(!Object.hasOwn(names,mode))return;state.timeMode=mode;state.night=mode==='night';refresh();}
 listen($('#time'),'click',()=>setTime(next[state.timeMode]));listen($('#orbit'),'click',()=>{ctx.setOrbit(!state.orbit);refresh()});for(const kind of['traffic','people'])listen($('#'+kind),'click',()=>{toast(kind+': '+simulation.cycle(kind));refresh()});listen($('#reset'),'click',()=>{focus('whole');refresh()});listen($('#pause'),'click',()=>{state.paused=!state.paused;refresh()});
 for(const b of document.querySelectorAll('[data-view]'))listen(b,'click',()=>{focus(b.dataset.view);refresh()});
 listen(window,'keydown',e=>{if(/^(INPUT|TEXTAREA|BUTTON|SELECT|SUMMARY|A)$/.test(e.target.tagName))return;if(e.key==='1')setTime('day');if(e.key==='2')setTime('sunset');if(e.key==='3')setTime('night');if(e.key.toLowerCase()==='r'||e.key==='Home')focus('whole');if(e.code==='Space'){e.preventDefault();state.paused=!state.paused;refresh()}});listen(document,'littleworldmotion',refresh);refresh();return{setTime,refresh,dispose(){clearTimeout(timer);listeners.forEach(f=>f())}};
}
